        ["CS0261"] = new[] { "All partial declarations of a type must be the same kind. For example, you cannot have one part declared as 'class' and another as 'struct' or 'interface'. Make them consistent." },
        ["CS0262"] = new[] { "Partial declarations must have consistent accessibility modifiers. For example, if one part is 'public', all parts must be 'public'. Check for conflicting modifiers like 'public' and 'internal'." },
        ["CS0263"] = new[] { "Partial declarations cannot specify different base classes. Only one part may specify a base class, or all parts must specify the same base class. Interfaces can be listed on multiple parts, but the base class must be consistent." },
