        ["CS0266"] = new[] { "An implicit conversion from the source type to the target type is not allowed because it may lose data or change the value. Add an explicit cast if the conversion is intentional, for example '(int)someLong', or use a checked conversion if overflow should be detected. If the conversion is not intended, change the target type or use a compatible type." },
