        ["CS0269"] = new[] { "The out parameter must be assigned before it is used inside the method. Assign a value to the out parameter on every code path before reading from it. The compiler does not consider an out parameter initially assigned." },
        ["CS0270"] = new[] { "Do not specify an array size in a variable declaration. For example, 'int[10] arr;' is invalid. Use 'int[] arr = new int[10];' instead. The size belongs in the array creation expression, not the type." },
        ["CS0271"] = new[] { "The get accessor of the property or indexer is not accessible from this context. Increase its accessibility, or access the property through a different member. Check for 'private set' or 'protected get' modifiers that restrict access." },
        ["CS0272"] = new[] { "The set accessor of the property or indexer is not accessible from this context. Increase its accessibility, or use a constructor or method to set the value. Check for 'private set' or 'protected set' modifiers." },
        ["CS0273"] = new[] { "The accessor accessibility must be more restrictive than the property or indexer accessibility. For example, a public property cannot have a public set accessor with a different modifier. Make the accessor modifier more restrictive, or remove it." },
        ["CS0274"] = new[] { "Do not specify accessibility modifiers on both accessors of a property or indexer. Only one accessor can have an accessibility modifier that differs from the property. Remove one of the modifiers." },
        ["CS0276"] = new[] { "An accessor accessibility modifier can only be used when both get and set accessors exist. If the property has only one accessor, remove the accessibility modifier from it." },
        ["CS0277"] = new[] { "The class implements an interface property but does not implement one of its accessors. Implement the missing get or set accessor, or use explicit interface implementation. Check the interface definition for required accessors." },
        ["CS0281"] = new[] { "The public key in the InternalsVisibleTo attribute does not match the public key of the current assembly. Ensure the friend assembly name and public key are correct, and that the friend assembly is signed with the matching key." },
        ["CS0283"] = new[] { "The type specified for a constant is not valid. Constants can only be of primitive types (bool, byte, char, decimal, double, float, int, long, sbyte, short, string, uint, ulong, ushort), enums, or reference types initialized with null. Change the type or remove 'const'." },
        ["CS0304"] = new[] { "You cannot create an instance of a type parameter without the 'new()' constraint. Add 'where T : new()' to the generic declaration, or avoid creating an instance of T. Alternatively, use Activator.CreateInstance or a factory delegate." },
