        ["CS0308"] = new[] { "The member is not generic, so you cannot provide type arguments. Remove the type argument list, or use a generic method or type instead." },
        ["CS0310"] = new[] { "The type argument does not satisfy the 'new()' constraint. The type must be a non-abstract type with a public parameterless constructor. Use a different type, or add a public parameterless constructor." },
        ["CS0311"] = new[] { "The type argument does not satisfy the 'class' constraint. Use a reference type as the type argument, or change the constraint to allow value types. Check for nullable value types or structs being used where a reference type is required." },
        ["CS0312"] = new[] { "The type argument is a nullable enum, but the constraint requires a non-nullable enum. Use the underlying enum type instead, or change the constraint. For example, use 'MyEnum' instead of 'MyEnum?'." },
