        ["CS0314"] = new[] { "The type argument does not satisfy the constraint because it cannot be converted to the constrained type parameter. Check the constraints on both type parameters, and ensure the type argument meets all requirements." },
        ["CS0315"] = new[] { "The type argument does not satisfy the 'struct' constraint. Use a non-nullable value type as the type argument, or change the constraint. Nullable value types and reference types are not allowed." },
        ["CS0316"] = new[] { "The parameter name conflicts with a compiler-generated name. Rename the parameter to avoid the conflict. This often happens with names like 'value' in property setters or event accessors." },
        ["CS0400"] = new[] { "The type or namespace name could not be found in the global namespace. Add a reference to the assembly that defines the type, or fully qualify the name. Check for missing using directives or misspelled names." },
        ["CS0401"] = new[] { "The 'new()' constraint must be the last constraint in the constraint clause. Move it to the end, after any class, struct, or interface constraints." },
        ["CS0403"] = new[] { "You cannot assign null to a type parameter because it might be a value type. Use 'default(T)' instead, or add a 'class' constraint if T is always a reference type." },
