        ["CS0439"] = new[] { "Extern alias declarations must appear before all other namespace elements. Move the extern alias declaration to the top of the file, before any using directives or type declarations." },
        ["CS0441"] = new[] { "A type cannot be both static and sealed. A static class is already implicitly sealed, so remove the sealed modifier." },
