        ["CS0701"] = new[] { "A constraint must be an interface, a non-sealed class, or a type parameter. Do not use a sealed class, a struct, an enum, or a special type as a constraint." },
        ["CS0702"] = new[] { "Special types such as System.Object, System.Array, System.Delegate, System.Enum, and System.ValueType cannot be used as generic constraints. Replace the constraint with an interface, a non-sealed class, or a type parameter. For example, use 'where T : class' instead of 'where T : object'." },
