        ["CS0706"] = new[] { "The type used as a constraint is not valid. A constraint must be an interface, a non-sealed class, a type parameter, or one of the special constraints class, struct, unmanaged, notnull, or new(). Do not use sealed classes, arrays, pointers, or special types." },
