        ["CS0715"] = new[] { "A static class cannot contain user-defined operators. Move the operator to a non-static class, or remove it. Operators require an instance type to operate on." },
        ["CS0716"] = new[] { "You cannot convert to a static type. Static types cannot be used as variables, return types, parameters, or generic type arguments. Use a non-static type, or make the type non-static." },
        ["CS0717"] = new[] { "A static class cannot be used as a generic constraint. Use an interface or a non-sealed class as the constraint, or make the class non-static." },
        ["CS0718"] = new[] { "A static type cannot be used as a generic type argument. Use a non-static type as the type argument, or make the type non-static." },
        ["CS0719"] = new[] { "An array element cannot be a static type. Use a non-static element type, or make the type non-static. Static types cannot be instantiated, so they cannot be array elements." },
        ["CS0720"] = new[] { "A static class cannot declare an indexer. Remove the indexer, or make the class non-static. Indexers require an instance receiver." },
        ["CS0721"] = new[] { "A static type cannot be used as a parameter type. Use a non-static type as the parameter, or make the type non-static." },
        ["CS0722"] = new[] { "A static type cannot be used as a return type. Use a non-static type as the return type, or make the type non-static." },
        ["CS0723"] = new[] { "You cannot declare a variable of a static type. Use a non-static type, or make the type non-static. Static types cannot be instantiated." },
