        ["CS0826"] = new[] { "The elements of an implicitly typed array must share a best common type. If the elements have different types, add explicit casts or specify the array type, for example 'new object[] { ... }'." },
        ["CS0828"] = new[] { "An anonymous type property cannot be assigned null, an anonymous function, a method group, or an expression with no type. Provide a concrete value or use an explicit type." },
        ["CS0831"] = new[] { "An expression tree cannot contain a base access. Use 'this' instead where possible, or move the base access outside the expression tree. Expression trees must be representable as data." },
        ["CS0832"] = new[] { "An expression tree cannot contain an assignment operator. Move the assignment outside the expression tree, or use a local variable. Expression trees support expressions, not statements." },
        ["CS0833"] = new[] { "An anonymous type cannot contain two properties with the same name. Rename one of the properties or use a different member name in the anonymous type initializer." },
        ["CS0834"] = new[] { "A statement lambda with a block body cannot be converted to an expression tree. Use an expression-bodied lambda, or convert the lambda to a delegate type instead of an expression tree." },
